17	  // エラーチェック
18	  if (error) {
19	    return redirect(`/login?error=${encodeURIComponent(error)}`);
20	  }
21	
22	  if (!code || !state) {
23	    return redirect('/login?error=invalid_callback');
24	  }
25	
26	  const cookieStore = await cookies();
27	  const savedState = cookieStore.get('oauth_state')?.value;
28	  const codeVerifier = cookieStore.get('oauth_code_verifier')?.value;
29	
30	  // CSRF チェック
31	  if (state !== savedState) {
32	    return redirect('/login?error=invalid_state');
33	  }
34	
35	  if (!codeVerifier) {
36	    return redirect('/login?error=missing_verifier');
37	  }
38	
39	  try {
40	    // トークンエンドポイントにリクエスト
41	    const oauthBaseUrl = (process.env.NEXT_PUBLIC_STEM_OAUTH_BASE_URL || 'http://localhost:3000/oauth').replace(/\/$/, '');
42	    const clientId = process.env.STEM_OAUTH_CLIENT_ID!;
43	    const clientSecret = process.env.STEM_OAUTH_CLIENT_SECRET!;
44	    const appUrl = (process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3001').replace(/\/$/, '');
45	    const redirectUri = `${appUrl}/auth/oauth/callback`;
46	
47	    const body = new URLSearchParams({
48	      grant_type: 'authorization_code',
49	      code,
50	      redirect_uri: redirectUri,
51	      client_id: clientId,
52	      client_secret: clientSecret,
53	      code_verifier: codeVerifier,
54	    });
55	
56	    const tokenResponse = await fetch(`${oauthBaseUrl}/token`, {
57	      method: 'POST',
58	      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
59	      body: body.toString(),
60	    });
61	
62	    if (!tokenResponse.ok) {
63	      const errorData = await tokenResponse.json();
64	      console.error('Token exchange failed:', errorData);
65	      return redirect(`/login?error=${encodeURIComponent(errorData.error || 'token_exchange_failed')}`);
66	    }
67	
68	    const { access_token } = await tokenResponse.json();
